-- Article 4: the scene of Gidi and Noa at the playground (״תראי!״ …
-- ״…ובסוף הוא יתרומם.״) is Ronit's own, not the book's, and is set as the
-- earlier articles set such a scene: the cream panel in the light face
-- (`opening`, no label), as article 3 opens with Gidi and Noa
-- (Ronit, 2026-10-27). Its paragraphs before and after stay running text.
-- No word changes.
--
-- Rewritten 2026-10-27 to touch that one block only (it becomes three), so
-- it can run before or after the other article-04 files. If the block is
-- not exactly as expected (already run, or edited in the admin), UPDATE 0.

UPDATE articles SET
  blocks = (
    SELECT jsonb_agg(x ORDER BY o, k)
    FROM jsonb_array_elements(blocks) WITH ORDINALITY AS t(e, o),
         LATERAL jsonb_array_elements(
           CASE WHEN e = $o${"type": "text", "body": "היכולת לחוות חולשה היא תנאי הכרחי לחוסן. היכולת להיות פגיע נמצאת בבסיס החוסן. היכולת להיות תלוי היא אחד הפירות של חוסן.\n\nחוסן הוא ההתגברות. כן. כולנו נופלים – כזאטוטים וכבוגרים. אם ננסה לצפות מראש את הנפילה הבאה ולהימנע ממנה, יש ונחסום את החיים עצמם. אנחנו לא בוחרים את הנפילה שהחיים מביאים לפתחנו. אנחנו בוחרים את ההתגברות.\n\nההתגברות מתחילה בליפול. מי שלא יודע ליפול, לא יודע להתגבר.\n\nעצמאות מתחילה בתלות. מי שלא יודע תלות נוחה, לא יודע עצמאות בטוחה.\n\n״תראי!״ גידי מאמץ את נועה אליו, ומתוך הכדור הקטן שהיא בתוך זרועותיו, היא מפנה את מבטה אל הבובה המתנפחת של ה״נחום-תקום״. היא עדיין מתייפחת, מבוהלת, על אף שהכלב שגדול ממנה כמעט פי שניים כבר הורחק לצידו השני של גן השעשועים. הנביחה הייתה לא צפויה. גידי חייב להודות שגם הוא החסיר פעימה. הוא מנסה להסיח את דעתה של נועה – דוחף בעדינות את הנחום-תקום, דוחף ועוזב. דוחף ועוזב.\n\n״תראי!״ גידי מדבר לאט. בשקט. הנשימות של נועה הולכות ונרגעות. היא מציצה, נוטשת מעט את ההיצמדות אל גופו הגדול. ״תראי – אנחנו נופלים, וקמים. נופלים, וקמים.״ ״ואם הוא לא יקום, אבא?״ גידי מחייך: ״הוא יקום. יש משקולת גדולה שם למטה. הוא לא יכול להישאר שוכב לתמיד. ניתן לו את הזמן שלו לשכב שם למטה, ובסוף הוא יתרומם.״\n\nגם אם לא זכינו לתלות מיטיבה בילדותנו, את המשקולת, את העוגן, את האמון בַּטּוֹב – אפשר לגדל. להעז ולבקש עזרה. לומר ״אני צריך״ ולהרגיש טוב עם עצמנו. אנחנו לא ״מקטרים״, לא ״מתמסכנים״, לא ״נופלים״ על מי שהציע לנו כתף."}$o$::jsonb THEN $n$[{"type": "text", "body": "היכולת לחוות חולשה היא תנאי הכרחי לחוסן. היכולת להיות פגיע נמצאת בבסיס החוסן. היכולת להיות תלוי היא אחד הפירות של חוסן.\n\nחוסן הוא ההתגברות. כן. כולנו נופלים – כזאטוטים וכבוגרים. אם ננסה לצפות מראש את הנפילה הבאה ולהימנע ממנה, יש ונחסום את החיים עצמם. אנחנו לא בוחרים את הנפילה שהחיים מביאים לפתחנו. אנחנו בוחרים את ההתגברות.\n\nההתגברות מתחילה בליפול. מי שלא יודע ליפול, לא יודע להתגבר.\n\nעצמאות מתחילה בתלות. מי שלא יודע תלות נוחה, לא יודע עצמאות בטוחה."}, {"type": "opening", "source": "free", "source_text": "", "body": "״תראי!״ גידי מאמץ את נועה אליו, ומתוך הכדור הקטן שהיא בתוך זרועותיו, היא מפנה את מבטה אל הבובה המתנפחת של ה״נחום-תקום״. היא עדיין מתייפחת, מבוהלת, על אף שהכלב שגדול ממנה כמעט פי שניים כבר הורחק לצידו השני של גן השעשועים. הנביחה הייתה לא צפויה. גידי חייב להודות שגם הוא החסיר פעימה. הוא מנסה להסיח את דעתה של נועה – דוחף בעדינות את הנחום-תקום, דוחף ועוזב. דוחף ועוזב.\n\n״תראי!״ גידי מדבר לאט. בשקט. הנשימות של נועה הולכות ונרגעות. היא מציצה, נוטשת מעט את ההיצמדות אל גופו הגדול. ״תראי – אנחנו נופלים, וקמים. נופלים, וקמים.״ ״ואם הוא לא יקום, אבא?״ גידי מחייך: ״הוא יקום. יש משקולת גדולה שם למטה. הוא לא יכול להישאר שוכב לתמיד. ניתן לו את הזמן שלו לשכב שם למטה, ובסוף הוא יתרומם.״"}, {"type": "text", "body": "גם אם לא זכינו לתלות מיטיבה בילדותנו, את המשקולת, את העוגן, את האמון בַּטּוֹב – אפשר לגדל. להעז ולבקש עזרה. לומר ״אני צריך״ ולהרגיש טוב עם עצמנו. אנחנו לא ״מקטרים״, לא ״מתמסכנים״, לא ״נופלים״ על מי שהציע לנו כתף."}]$n$::jsonb
                ELSE jsonb_build_array(e) END
         ) WITH ORDINALITY AS u(x, k)
  ),
  updated_at = now()
WHERE id = 18 AND slug = 'article-04'
  AND EXISTS (SELECT 1 FROM jsonb_array_elements(blocks) e WHERE e = $o${"type": "text", "body": "היכולת לחוות חולשה היא תנאי הכרחי לחוסן. היכולת להיות פגיע נמצאת בבסיס החוסן. היכולת להיות תלוי היא אחד הפירות של חוסן.\n\nחוסן הוא ההתגברות. כן. כולנו נופלים – כזאטוטים וכבוגרים. אם ננסה לצפות מראש את הנפילה הבאה ולהימנע ממנה, יש ונחסום את החיים עצמם. אנחנו לא בוחרים את הנפילה שהחיים מביאים לפתחנו. אנחנו בוחרים את ההתגברות.\n\nההתגברות מתחילה בליפול. מי שלא יודע ליפול, לא יודע להתגבר.\n\nעצמאות מתחילה בתלות. מי שלא יודע תלות נוחה, לא יודע עצמאות בטוחה.\n\n״תראי!״ גידי מאמץ את נועה אליו, ומתוך הכדור הקטן שהיא בתוך זרועותיו, היא מפנה את מבטה אל הבובה המתנפחת של ה״נחום-תקום״. היא עדיין מתייפחת, מבוהלת, על אף שהכלב שגדול ממנה כמעט פי שניים כבר הורחק לצידו השני של גן השעשועים. הנביחה הייתה לא צפויה. גידי חייב להודות שגם הוא החסיר פעימה. הוא מנסה להסיח את דעתה של נועה – דוחף בעדינות את הנחום-תקום, דוחף ועוזב. דוחף ועוזב.\n\n״תראי!״ גידי מדבר לאט. בשקט. הנשימות של נועה הולכות ונרגעות. היא מציצה, נוטשת מעט את ההיצמדות אל גופו הגדול. ״תראי – אנחנו נופלים, וקמים. נופלים, וקמים.״ ״ואם הוא לא יקום, אבא?״ גידי מחייך: ״הוא יקום. יש משקולת גדולה שם למטה. הוא לא יכול להישאר שוכב לתמיד. ניתן לו את הזמן שלו לשכב שם למטה, ובסוף הוא יתרומם.״\n\nגם אם לא זכינו לתלות מיטיבה בילדותנו, את המשקולת, את העוגן, את האמון בַּטּוֹב – אפשר לגדל. להעז ולבקש עזרה. לומר ״אני צריך״ ולהרגיש טוב עם עצמנו. אנחנו לא ״מקטרים״, לא ״מתמסכנים״, לא ״נופלים״ על מי שהציע לנו כתף."}$o$::jsonb);
